    #[tokio::test]
    async fn failing_staged_version_aborts_and_cleans_up_remote_temp() {
        let dir = tempdir().unwrap();
        let paths = Paths::under(dir.path());
        let fleet = sample_fleet();
        let signing = SigningKey::from_bytes(&[0x36; 32]);
        let pubkey = signing.verifying_key().to_bytes();
        let payload = fake_binary("x86_64-unknown-linux-musl", b"broken-exec");
        let mut backend = FakeInstallBackend::linux_x86_64("0.2.0", Some("0.1.0"), "0.2.0")
            .with_release(
                "0.2.0",
                "x86_64-unknown-linux-musl",
                &payload,
                Some(&signing),
            );
        backend.staged_version_output = Some(RemoteCommandOutput {
            success: false,
            stdout: String::new(),
            stderr: "Exec format error".to_owned(),
        });

        let err = run_fleet_install_with_key(
            &paths,
            &fleet,
            "laptop",
            &backend,
            &pubkey,
            InstallArgs {
                machine: "tower".to_owned(),
                version: Some("0.2.0".to_owned()),
                from: None,
                dry_run: false,
                allow_downgrade: false,
            },
            CancellationToken::new(),
        )
        .await
        .unwrap_err();
        assert_eq!(err.code, ErrorCode::Failed);
        assert!(err.message.contains("--version"), "{}", err.message);
        let ssh_cmds = backend.ssh_log.lock().unwrap();
        assert!(
            ssh_cmds
                .iter()
                .any(|(_, cmd)| cmd.contains("rm -f \"$HOME/.local/bin/.legion-install-")),
            "expected remote temp cleanup"
        );
        assert!(
            !ssh_cmds.iter().any(|(_, cmd)| cmd.contains("mv -f")),
            "finalize move must not run when staged --version fails"
        );
        assert!(backend.session_checks.lock().unwrap().is_empty());
    }

    #[tokio::test]
    async fn post_install_session_failure_rolls_back_from_prev_and_reports_restoration() {
        let dir = tempdir().unwrap();
        let paths = Paths::under(dir.path());
        let fleet = sample_fleet();
        let signing = SigningKey::from_bytes(&[0x37; 32]);
        let pubkey = signing.verifying_key().to_bytes();
        let payload = fake_binary("x86_64-unknown-linux-musl", b"bad-session");
        let mut backend = FakeInstallBackend::linux_x86_64("0.2.0", Some("0.1.0"), "0.2.0")
            .with_release(
                "0.2.0",
                "x86_64-unknown-linux-musl",
                &payload,
                Some(&signing),
            );
        backend.fail_session = true;

        let err = run_fleet_install_with_key(
            &paths,
            &fleet,
            "laptop",
            &backend,
            &pubkey,
            InstallArgs {
                machine: "tower".to_owned(),
                version: Some("0.2.0".to_owned()),
                from: None,
                dry_run: false,
                allow_downgrade: false,
            },
            CancellationToken::new(),
        )
        .await
        .unwrap_err();
        assert!(
            err.message.contains("restored") && err.message.contains(".prev"),
            "{}",
            err.message
        );
        assert!(
            backend
                .ssh_log
                .lock()
                .unwrap()
                .iter()
                .any(|(_, cmd)| cmd.contains("mv -f \"$d.prev\" \"$d\"")),
            "expected remote rollback from .prev"
        );
    }

    #[tokio::test]
    async fn parses_old_and_new_version_lines_and_reports_installed_build() {
        assert_eq!(
            parse_version_output("legion 0.1.0\n").as_deref(),
            Some("0.1.0")
        );
        assert_eq!(
            parse_version_output("legion 0.1.0 (a59ec0d12345)\n").as_deref(),
            Some("0.1.0")
        );
        assert_eq!(
            parse_version_output("legion 0.1.0 (a59ec0d12345, modified)\r\n").as_deref(),
            Some("0.1.0")
        );

        let dir = tempdir().unwrap();
        let paths = Paths::under(dir.path());
        let fleet = sample_fleet();
        let local_bin = dir.path().join("legion-rebuilt");
        fs::write(
            &local_bin,
            fake_binary("x86_64-unknown-linux-musl", b"rebuilt-same-version"),
        )
        .unwrap();

        let mut backend = FakeInstallBackend::linux_x86_64("0.1.0", None, "0.1.0");
        backend.previous_version_output = Some("legion 0.1.0 (111111111111)\n".to_owned());
        backend.staged_version_output = Some(RemoteCommandOutput {
            success: true,
            stdout: "legion 0.1.0 (222222222222, modified)\n".to_owned(),
            stderr: String::new(),
        });
        backend.session_build_after_install = Some("222222222222, modified".to_owned());

        let res = run_fleet_install(
            &paths,
            &fleet,
            "laptop",
            &backend,
            InstallArgs {
                machine: "tower".to_owned(),
                version: None,
                from: Some(local_bin.display().to_string()),
                dry_run: false,
                allow_downgrade: false,
            },
            CancellationToken::new(),
        )
        .await
        .unwrap();
        assert_eq!(res.previous_version.as_deref(), Some("0.1.0"));
        assert_eq!(res.installed_version, "0.1.0");
        assert_eq!(res.build.as_deref(), Some("222222222222, modified"));
    }

    #[tokio::test]
    async fn fleet_install_refuses_package_managed_remote_without_copying_anything() {
        let dir = tempdir().unwrap();
        let paths = Paths::under(dir.path());
        let fleet = sample_fleet();
        let local_bin = dir.path().join("legion-custom");
        fs::write(
            &local_bin,
            fake_binary("x86_64-unknown-linux-musl", b"local-binary"),
        )
        .unwrap();

        let parsed = parse_remote_dest_probe(
            "LEGION_DEST=/usr/bin/legion\nLEGION_MANAGED_BY=deb\nLEGION_WRITABLE=no\n",
        )
        .unwrap();
        assert_eq!(parsed.managed_by, Some(PackageManager::Deb));
        assert!(!parsed.writable);

        for (marker, expected_hint) in [("deb", "apt-get install"), ("pacman", "pacman")] {
            let mut backend = FakeInstallBackend::linux_x86_64("0.2.0", Some("0.1.0"), "0.2.0");
            // Even if writable=yes (e.g. root SSH), package-managed installs must still be refused.
            backend.dest_probe_output = Some(RemoteCommandOutput {
                success: true,
                stdout: format!(
                    "LEGION_DEST=/usr/bin/legion\nLEGION_MANAGED_BY={marker}\nLEGION_WRITABLE=yes\n"
                ),
                stderr: String::new(),
            });

            for (dry_run, from) in [
                (false, None),
                (true, None),
                (false, Some(local_bin.display().to_string())),
            ] {
                let err = run_fleet_install(
                    &paths,
                    &fleet,
                    "laptop",
                    &backend,
                    InstallArgs {
                        machine: "tower".to_owned(),
                        version: None,
                        from,
                        dry_run,
                        allow_downgrade: false,
                    },
                    CancellationToken::new(),
                )
                .await
                .unwrap_err();
                assert_eq!(err.code, ErrorCode::Unsupported);
                assert_eq!(err.machine.as_deref(), Some("tower"));
                assert!(err.message.contains("/usr/bin/legion"), "{}", err.message);
                assert!(
                    err.hint.as_deref().unwrap().contains(expected_hint),
                    "{:?}",
                    err.hint
                );
                assert_eq!(err.details.as_ref().unwrap()["managed_by"], marker);
            }

            assert!(backend.download_log.lock().unwrap().is_empty());
            assert!(backend.scp_log.lock().unwrap().is_empty());
            assert!(backend.session_checks.lock().unwrap().is_empty());
        }
    }
